// Paging without recomposing on every pixel of scroll
@Composable
fun PagedList(state: LazyListState, onLoadMore: () -> Unit) {
  LaunchedEffect(state) {
    snapshotFlow { state.layoutInfo.visibleItemsInfo.lastOrNull()?.index }
      .distinctUntilChanged()
      .collect { last -> if (last != null && last >= state.layoutInfo.totalItemsCount - 5) onLoadMore() }
  }
}

