@Composable
fun MapPanel(zoom: Float, modifier: Modifier = Modifier) {
  val lifecycleOwner = LocalLifecycleOwner.current
  val mapView = remember { mutableStateOf<MapView?>(null) }

  DisposableEffect(lifecycleOwner) {
    val observer = LifecycleEventObserver { _, event ->
      when (event) {
        Lifecycle.Event.ON_START -> mapView.value?.onStart()
        Lifecycle.Event.ON_STOP -> mapView.value?.onStop()
        else -> Unit
      }
    }
    lifecycleOwner.lifecycle.addObserver(observer)
    onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
  }

  AndroidView(
    modifier = modifier,
    factory = { context -> MapView(context).also { mapView.value = it } },
    update = { it.setZoom(zoom) },          // runs when zoom changes
    onRelease = { it.onDestroy() },
  )
}

