@Composable
fun InboxScreen(events: Flow<UiEvent>, onCompose: () -> Unit) {
  val hostState = remember { SnackbarHostState() }
  val scope = rememberCoroutineScope()
  val scrollBehavior = TopAppBarDefaults.enterAlwaysScrollBehavior()

  // One-shot events from the ViewModel become snackbars here, not in the body.
  LaunchedEffect(Unit) {
    events.collect { event ->
      val result = hostState.showSnackbar(
        message = event.message,
        actionLabel = "Undo",
        duration = SnackbarDuration.Short,
      )
      if (result == SnackbarResult.ActionPerformed) event.undo()
    }
  }

  Scaffold(
    modifier = Modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
    topBar = {
      LargeTopAppBar(
        title = { Text("Inbox") },
        scrollBehavior = scrollBehavior,   // same object as the nestedScroll one
      )
    },
    snackbarHost = { SnackbarHost(hostState) },
    floatingActionButton = {
      FloatingActionButton(onClick = onCompose) {
        Icon(Icons.Default.Edit, contentDescription = "Compose")
      }
    },
  ) { innerPadding ->
    LazyColumn(contentPadding = innerPadding) {   // insets as contentPadding
      items(messages, key = { it.id }) { message ->
        MessageRow(message, onArchive = {
          scope.launch { hostState.showSnackbar("Archived") }
        })
      }
    }
  }
}

