// RIGHT: a genuine custom gesture — keys restart the block, semantics make it
// reachable, and consuming the drag stops the list from scrolling with it.
@Composable
fun SwipeToArchive(item: Item, onArchive: (Item) -> Unit) {
  var offsetX by remember { mutableFloatStateOf(0f) }
  val latestArchive by rememberUpdatedState(onArchive)

  Box(
    Modifier
      .offset { IntOffset(offsetX.roundToInt(), 0) }   // read in layout, not composition
      .pointerInput(item.id) {
        detectHorizontalDragGestures(
          onHorizontalDrag = { change, delta ->
            offsetX += delta
            change.consume()                            // do not let the list scroll
          },
          onDragEnd = {
            if (offsetX > 200f) latestArchive(item) else offsetX = 0f
          },
        )
      }
      .semantics {
        customActions = listOf(
          CustomAccessibilityAction("Archive") { latestArchive(item); true }
        )
      }
  ) { Text(item.title) }
}

