@Composable
fun OrderScreen(vm: OrderViewModel) {
  // A nullable target doubles as the flag and as the sheet's content.
  var editing by rememberSaveable(stateSaver = ItemSaver) { mutableStateOf<Item?>(null) }
  var confirmDelete by rememberSaveable { mutableStateOf(false) }
  val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
  val scope = rememberCoroutineScope()

  OrderList(onEdit = { editing = it }, onDelete = { confirmDelete = true })

  editing?.let { item ->
    ModalBottomSheet(
      onDismissRequest = { editing = null },   // swipe, scrim tap, back
      sheetState = sheetState,
    ) {
      ItemEditor(
        item = item,
        onSave = { updated ->
          vm.save(updated)
          // Animate out first, THEN leave the composition.
          scope.launch { sheetState.hide() }.invokeOnCompletion {
            if (!sheetState.isVisible) editing = null
          }
        },
      )
    }
  }

  if (confirmDelete) {
    AlertDialog(
      onDismissRequest = { confirmDelete = false },
      icon = { Icon(Icons.Default.Warning, contentDescription = null) },
      title = { Text("Delete order?") },
      text = { Text("This cannot be undone.") },
      confirmButton = {
        TextButton(onClick = { vm.delete(); confirmDelete = false }) { Text("Delete") }
      },
      dismissButton = {
        TextButton(onClick = { confirmDelete = false }) { Text("Cancel") }
      },
    )
  }
}

