// Roughly what the plugin emits — the $composer is why the call must come
// from another composable, and the group is the identity of `remember`.
fun Greeting(name: String, $composer: Composer, $changed: Int) {
  $composer.startRestartGroup(0x7A31)
  if ($changed and 0b1011 != 0b0010 || !$composer.skipping) {
    val id = $composer.cache(false) { UUID.randomUUID() }
    Text("$name $id", $composer, 0)
  } else {
    $composer.skipToGroupEnd()              // parameters unchanged: skip
  }
  $composer.endRestartGroup()?.updateScope { c, _ -> Greeting(name, c, $changed or 1) }
}

// WRONG: identity is the loop position, so reordering hands row 0 the state
// (and the remembered id) of whatever used to be first.
@Composable
fun ListBad(items: List<Item>) {
  Column {
    items.forEach { item ->
      var expanded by remember { mutableStateOf(false) }
      Row(item, expanded) { expanded = !expanded }
    }
  }
}

// RIGHT: key() opens a movable group, so state travels with the item.
@Composable
fun ListGood(items: List<Item>) {
  Column {
    items.forEach { item ->
      key(item.id) {
        var expanded by remember { mutableStateOf(false) }
        Row(item, expanded) { expanded = !expanded }
      }
    }
  }
}

// BEFORE: a composition per call site, nothing comparable, state read in
// composition — every recomposition rebuilds this piece of the chain.
fun Modifier.dotBad(color: Color) = composed {
  val alpha by animateFloatAsState(if (color == Color.Red) 1f else 0.5f, label = "a")
  drawBehind { drawCircle(color = color, radius = 6.dp.toPx(), alpha = alpha) }
}

// AFTER: a value + a node.
private data class DotElement(val color: Color) : ModifierNodeElement<DotNode>() {
  override fun create() = DotNode(color)

  // Same instance, new parameter: mutate it, do not allocate a new node.
  override fun update(node: DotNode) {
    node.color = color
    node.invalidateDraw()                 // redraw only; no recomposition
  }

  override fun InspectorInfo.inspectableProperties() {
    name = "dot"
    properties["color"] = color
  }
}

private class DotNode(var color: Color) : Modifier.Node(), DrawModifierNode {
  private val alpha = Animatable(1f)

  override fun onAttach() {               // lifecycle composed never had
    coroutineScope.launch {
      alpha.animateTo(0.4f, infiniteRepeatable(tween(800), RepeatMode.Reverse))
    }
  }

  override fun ContentDrawScope.draw() {
    drawContent()
    // alpha is read in the draw phase, so a frame costs a redraw, not a
    // recomposition of the subtree above.
    drawCircle(color = color, radius = 6.dp.toPx(), alpha = alpha.value)
  }
}

fun Modifier.dot(color: Color): Modifier = this then DotElement(color)
